INSERT INTO flashcards (id, deck_id, front_text, back_text, phonetic, example_text, hint, note, card_order, is_active, created_by, created_at, updated_at) VALUES (10153, 1010, 'accountant', 'nhân viên kế toán', '/əˈkaʊn.tənt/', 'The chief accountant verified the annual financial statements.', 'n. | Finance & Accounting', 'CEFR: B2 | Source: Oxford 5000 (p.1) | POS: n.', 1, 1, @admin_id, NOW(), NOW());
